  const knownThrough=(r.cancelled&&r.updateDate&&r.updateDate<r.endDate)?r.updateDate:(!confirmedEnded&&r.updateDate&&r.updateDate<r.endDate)?cpcPrevDay(r.updateDate):r.endDate;
