    const w=(grp,f,val)=>{const c=g(grp,f);if(c!=null)set(rn,c+1,val);};
    w("Dine-In","Disc",psRound(v.di.disc,2));w("Dine-In","Sales",psRound(v.di.sales,2));w("Dine-In","Orders",v.di.orders);w("Dine-In","AOV",aov(v.di.sales,v.di.orders));
