    if(f.textFormat){const t={};const tf=[];for(const k of["fontFamily","fontSize","bold"])if(f.textFormat[k]!=null){t[k]=f.textFormat[k];tf.push("textFormat."+k);}if(tf.length){o.textFormat=t;fl.push(...tf);}}
