  for(const[a,b]of[[3,9],[9,13],[13,17]])R.push({mergeCells:{range:{sheetId:D,startRowIndex:0,endRowIndex:1,startColumnIndex:a,endColumnIndex:b},mergeType:"MERGE_ALL"}});
