  const f=v=>"AED "+Math.round(v).toLocaleString(),f2=v=>(v<0?"−":"")+"AED "+Math.abs(Math.round(v)).toLocaleString();
  const tp=R.reduce((a,r)=>a+r.pos,0),ta=R.reduce((a,r)=>a+r.agg,0);
