  const cat=sumO("catering"),test=sumO("test"),unk=items.reduce((a,i)=>a+(i.open?i.unk:0),0);
  const acked=items.reduce((a,i)=>a+(i.ack?i.unexpl:0),0),small=items.reduce((a,i)=>a+(!i.ack&&!i.open?i.unexpl:0),0);
