  const del=(lensBase||allData).filter(r=>r.channel!=="instore"&&r.branch!=="(brand-level)"),days=[];for(let i=13;i>=0;i--)days.push(subDays(latest,i));const ix={};days.forEach((d,i)=>ix[d]=i);
